import type { AlarmRecord, DeviceEntity, UserSession, WorkOrderRecord, WorkOrderStatus } from '@pacom/contracts';
import { E7F_IDS, type PacomDataAdapter } from '../../adapters';

const WO_STATUS_LABELS: Record<WorkOrderStatus, string> = {
  open: '待分派',
  assigned: '已指派',
  in_progress: '处理中',
  resolved: '已解决',
  closed: '已关闭',
};

const SEVERITY_META: Record<string, { label: string; cls: string }> = {
  critical: { label: '严重', cls: 'pacom-badge--critical' },
  major: { label: '重要', cls: 'pacom-badge--warning' },
  minor: { label: '一般', cls: 'pacom-badge--accent' },
  info: { label: '提示', cls: 'pacom-badge--neutral' },
};

const ZONE_LABELS: Record<string, string> = {
  'zone-e7f-lab-east': '东侧实验区',
  'zone-e7f-office-west': '西侧办公区',
  'zone-e7f-meeting-702': '702 会议室',
  'zone-e7f-corridor': '核心走廊与弱电井',
};

function getRecommendation(a: AlarmRecord): string {
  const txt = `${a.title} ${a.message}`.toLowerCase();
  if (txt.includes('离线') || txt.includes('modbus') || txt.includes('心跳')) {
    return '建议先在「系统部署 → 系统接入」核查边缘网关与 RS485/Modbus 链路状态，排除通信中断后再派单现场排查。';
  }
  if (txt.includes('co₂') || txt.includes('co2') || txt.includes('新风')) {
    return '建议在「空间总览」提高该区域新风/空调风速，或前往「智能策略」检查 CO₂ 联动阈值。';
  }
  return '建议先点击右侧「定位到空间总览」查看实时遥测与设备工况，确认后可标记已处置或一键转工单。';
}

export async function mountAlarmsView(
  root: HTMLElement,
  adapter: PacomDataAdapter,
  session: UserSession
): Promise<void> {
  let alarms: AlarmRecord[] = [];
  let workOrders: WorkOrderRecord[] = [];
  let devices: DeviceEntity[] = [];
  let activeTab: 'alarms' | 'workorders' = 'alarms';
  let statusFilter: 'all' | 'active' | 'acknowledged' | 'snoozed' = 'all';
  let severityFilter = 'all';
  let openWoOnly = false;
  let groupByRootCause = false;
  let searchQuery = '';
  let expandedAlarmId: string | null = null;
  const selectedAlarmIds = new Set<string>();
  const snoozedIds = new Set<string>();
  const selfActionedIds = new Set<string>();
  let notice = '';
  let errorMsg = '';

  async function refresh(): Promise<void> {
    [alarms, workOrders, devices] = await Promise.all([
      adapter.listAlarms(E7F_IDS.floorId),
      adapter.listWorkOrders(E7F_IDS.floorId),
      adapter.getFloorDevices(E7F_IDS.floorId).catch(() => []),
    ]);
    render();
  }

  function resolveDeviceDisplay(deviceId?: string | null): { name: string; zone: string } {
    if (!deviceId) return { name: '楼层通用', zone: 'E7F' };
    const found = devices.find((d) => d.id === deviceId);
    if (!found) return { name: deviceId, zone: 'E7F' };
    return {
      name: found.name,
      zone: (found.logicalZoneId ? ZONE_LABELS[found.logicalZoneId] : undefined) ?? 'E7F',
    };
  }

  function render(): void {
    const activeAlarms = alarms.filter((a) => a.status === 'active' && !snoozedIds.has(a.id));
    const inProgressWo = workOrders.filter((w) => w.status === 'open' || w.status === 'assigned' || w.status === 'in_progress');
    const ackCount = alarms.filter((a) => a.status !== 'active').length + selfActionedIds.size;
    const snoozedCount = snoozedIds.size;

    const q = searchQuery.trim().toLowerCase();
    const filteredAlarms = alarms.filter((a) => {
      const isSnoozed = snoozedIds.has(a.id);
      if (statusFilter === 'snoozed') {
        if (!isSnoozed) return false;
      } else if (statusFilter === 'active') {
        if (a.status !== 'active' || isSnoozed) return false;
      } else if (statusFilter === 'acknowledged') {
        if (a.status !== 'acknowledged') return false;
      } else if (isSnoozed) {
        return false;
      }
      if (severityFilter !== 'all' && a.severity !== severityFilter) return false;
      if (!q) return true;
      const dev = resolveDeviceDisplay(a.deviceId);
      return `${a.title} ${a.message} ${dev.name} ${dev.zone} ${a.deviceId}`.toLowerCase().includes(q);
    });

    const groupedMap = new Map<string, AlarmRecord[]>();
    for (const a of filteredAlarms) {
      const key = groupByRootCause ? a.deviceId : a.id;
      const list = groupedMap.get(key) ?? [];
      list.push(a);
      groupedMap.set(key, list);
    }
    const displayRows = Array.from(groupedMap.values());

    const visibleWorkOrders = workOrders.filter((w) => {
      if (openWoOnly && (w.status === 'resolved' || w.status === 'closed')) return false;
      if (!q) return true;
      const dev = resolveDeviceDisplay(w.deviceId);
      return `${w.title} ${w.description} ${w.id} ${dev.name}`.toLowerCase().includes(q);
    });

    const filterLabel =
      statusFilter === 'active'
        ? '仅看待处理'
        : statusFilter === 'acknowledged'
          ? '仅看已确认'
          : statusFilter === 'snoozed'
            ? '仅看已忽略 24h'
            : '';

    root.innerHTML = `
      <div class="pacom-shell">
        <header class="pacom-header">
          <div class="pacom-header-top">
            <div style="display:flex; align-items:center; gap:14px; flex-wrap:wrap;">
              <h1 class="pacom-title">告警中心</h1>
              <div class="pacom-tabs" role="tablist" aria-label="告警中心视图">
                <button class="pacom-tab" role="tab" aria-selected="${activeTab === 'alarms'}" data-main-tab="alarms">
                  实时告警（${alarms.length - snoozedCount}）
                </button>
                <button class="pacom-tab" role="tab" aria-selected="${activeTab === 'workorders'}" data-main-tab="workorders">
                  运维工单（${workOrders.length}）
                </button>
              </div>
            </div>

            <div class="pacom-header-meta">
              ${
                activeTab === 'alarms'
                  ? `
                  <label style="display:inline-flex; align-items:center; gap:8px; font-size:13px; color:var(--pacom-text-body); cursor:pointer;">
                    <span>根因归并</span>
                    <button type="button" class="lov-switch" role="switch" aria-checked="${groupByRootCause}" data-toggle-group="1" aria-label="按设备根因归并">
                      <span class="lov-switch-thumb"></span>
                    </button>
                  </label>`
                  : `
                  <label style="display:inline-flex; align-items:center; gap:8px; font-size:13px; color:var(--pacom-text-body); cursor:pointer;">
                    <span>仅看未结工单</span>
                    <button type="button" class="lov-switch" role="switch" aria-checked="${openWoOnly}" data-toggle-open-wo="1" aria-label="仅看未结工单">
                      <span class="lov-switch-thumb"></span>
                    </button>
                  </label>`
              }
              <span class="pacom-badge ${session.scope.canManageAlarms ? 'pacom-badge--online' : 'pacom-badge--warning'}">
                ${session.scope.canManageAlarms ? '可处置与转单' : '只读权限'}
              </span>
              <button class="lov-icon-btn" data-refresh-alarms="1" title="刷新告警与工单" aria-label="刷新告警与工单">↻</button>
            </div>
          </div>
        </header>

        <div class="pacom-content-page" style="padding:4px 0 24px;">
          <div class="lov-kpi-strip" role="region" aria-label="告警闭环状态筛选">
            <button type="button" class="lov-kpi-cell" data-kpi-filter="active"
              style="border:0; background:transparent; text-align:left; cursor:pointer; ${activeTab === 'alarms' && statusFilter === 'active' ? 'box-shadow:inset 0 -2px 0 var(--pacom-accent-solid); background:var(--pacom-hover-layer);' : ''}">
              <span class="lov-kpi-label">待处理告警</span>
              <div class="lov-kpi-value">${activeAlarms.length}<span class="lov-kpi-unit">条</span></div>
              <span class="lov-kpi-delta">点击快速筛选待处理</span>
            </button>
            <button type="button" class="lov-kpi-cell" data-kpi-filter="workorders"
              style="border:0; background:transparent; text-align:left; cursor:pointer; ${activeTab === 'workorders' && openWoOnly ? 'box-shadow:inset 0 -2px 0 var(--pacom-accent-solid); background:var(--pacom-hover-layer);' : ''}">
              <span class="lov-kpi-label">处理中工单</span>
              <div class="lov-kpi-value">${inProgressWo.length}<span class="lov-kpi-unit">单</span></div>
              <span class="lov-kpi-delta">点击聚焦未结工单</span>
            </button>
            <button type="button" class="lov-kpi-cell" data-kpi-filter="acknowledged"
              style="border:0; background:transparent; text-align:left; cursor:pointer; ${activeTab === 'alarms' && statusFilter === 'acknowledged' ? 'box-shadow:inset 0 -2px 0 var(--pacom-accent-solid); background:var(--pacom-hover-layer);' : ''}">
              <span class="lov-kpi-label">已确认 / 闭环</span>
              <div class="lov-kpi-value">${ackCount}<span class="lov-kpi-unit">项</span></div>
              <span class="lov-kpi-delta">24h 无复发即计入有效</span>
            </button>
            <button type="button" class="lov-kpi-cell" data-kpi-filter="snoozed"
              style="border:0; background:transparent; text-align:left; cursor:pointer; ${activeTab === 'alarms' && statusFilter === 'snoozed' ? 'box-shadow:inset 0 -2px 0 var(--pacom-accent-solid); background:var(--pacom-hover-layer);' : ''}">
              <span class="lov-kpi-label">已忽略 24h</span>
              <div class="lov-kpi-value">${snoozedCount}<span class="lov-kpi-unit">条</span></div>
              <span class="lov-kpi-delta">到期自动恢复监控</span>
            </button>
          </div>

          ${notice ? `<div class="lov-banner lov-banner--ok"><span class="lov-banner-title">${notice}</span></div>` : ''}
          ${errorMsg ? `<div class="pacom-alert-banner">${errorMsg}</div>` : ''}

          ${
            activeTab === 'alarms'
              ? `
              <section class="lov-table-card">
                <div class="lov-table-toolbar">
                  <div class="lov-table-toolbar-group" style="flex:1; min-width:240px;">
                    <input class="pacom-input" style="max-width:260px;" data-alarm-search placeholder="搜索告警、设备或功能区…" value="${searchQuery}" aria-label="搜索告警" />
                    <select class="pacom-select" data-severity-filter aria-label="按告警级别筛选">
                      <option value="all" ${severityFilter === 'all' ? 'selected' : ''}>全部级别</option>
                      <option value="critical" ${severityFilter === 'critical' ? 'selected' : ''}>严重</option>
                      <option value="major" ${severityFilter === 'major' ? 'selected' : ''}>重要</option>
                      <option value="minor" ${severityFilter === 'minor' ? 'selected' : ''}>一般</option>
                    </select>
                    ${
                      filterLabel
                        ? `<button type="button" class="pacom-btn pacom-btn--ghost" data-clear-kpi="1">${filterLabel} ×</button>`
                        : ''
                    }
                  </div>
                  <div class="lov-table-toolbar-group">
                    ${
                      selectedAlarmIds.size > 0 && session.scope.canManageAlarms
                        ? `<button type="button" class="pacom-btn pacom-btn--primary" data-batch-ack="1">批量确认（${selectedAlarmIds.size}）</button>`
                        : ''
                    }
                    <span class="pacom-row-sub">共 ${displayRows.length} 项</span>
                  </div>
                </div>
                ${
                  displayRows.length === 0
                    ? `<div class="lov-empty-state"><strong>当前条件下无告警</strong><span>楼层运行平稳，可点击上方 KPI 卡片或清空筛选查看全部记录。</span></div>`
                    : `
                    <div class="lov-table-wrap">
                      <table class="lov-table">
                        <thead>
                          <tr>
                            <th style="width:36px;"></th>
                            <th>级别</th>
                            <th>告警事项</th>
                            <th>设备与空间</th>
                            <th>触发时间</th>
                            <th>状态</th>
                            <th style="text-align:right;">操作</th>
                          </tr>
                        </thead>
                        <tbody>
                          ${displayRows
                            .map((group) => {
                              const a = group[0]!;
                              const sev = SEVERITY_META[a.severity] ?? { label: a.severity, cls: 'pacom-badge--neutral' };
                              const dev = resolveDeviceDisplay(a.deviceId);
                              const isExpanded = expandedAlarmId === a.id;
                              const isSnoozed = snoozedIds.has(a.id);
                              const isChecked = selectedAlarmIds.has(a.id);
                              return `
                                <tr>
                                  <td>
                                    <input type="checkbox" data-check-alarm="${a.id}" ${isChecked ? 'checked' : ''} ${a.status !== 'active' || isSnoozed ? 'disabled' : ''} aria-label="选择 ${a.title}" />
                                  </td>
                                  <td><span class="pacom-badge ${sev.cls}">${sev.label}</span></td>
                                  <td>
                                    <div style="font-weight:500; display:flex; align-items:center; gap:6px;">
                                      <span>${a.title}</span>
                                      ${group.length > 1 ? `<span class="pacom-badge pacom-badge--accent">归并 ${group.length} 条</span>` : ''}
                                    </div>
                                    <div class="pacom-row-sub">${a.message}</div>
                                  </td>
                                  <td>
                                    <div style="font-weight:500;">${dev.name}</div>
                                    <div class="pacom-row-sub">${dev.zone}</div>
                                  </td>
                                  <td><span class="pacom-row-sub">${a.triggeredAt ? a.triggeredAt.slice(5, 16).replace('T', ' ') : '-'}</span></td>
                                  <td>
                                    <span class="pacom-badge ${isSnoozed ? 'pacom-badge--neutral' : a.status === 'active' ? 'pacom-badge--warning' : 'pacom-badge--online'}">
                                      ${isSnoozed ? '已忽略 24h' : a.status === 'active' ? '待处理' : '已确认'}
                                    </span>
                                  </td>
                                  <td>
                                    <div style="display:flex; justify-content:flex-end; gap:6px; align-items:center;">
                                      ${
                                        isSnoozed
                                          ? `<button class="pacom-btn" data-unsnooze="${a.id}">恢复监控</button>`
                                          : `
                                            ${a.status === 'active' ? `<button class="pacom-btn" data-mark-actioned="${a.id}" ${!session.scope.canManageAlarms ? 'disabled' : ''}>标记已处置</button>` : ''}
                                            ${!a.workOrderId ? `<button class="pacom-btn pacom-btn--primary" data-to-wo="${a.id}" ${!session.scope.canManageAlarms ? 'disabled' : ''}>转工单</button>` : `<span class="pacom-badge pacom-badge--accent">已转单</span>`}
                                          `
                                      }
                                      <button class="pacom-btn pacom-btn--ghost" data-expand-alarm="${a.id}">${isExpanded ? '收起' : '详情'}</button>
                                    </div>
                                  </td>
                                </tr>
                                ${
                                  isExpanded
                                    ? `
                                    <tr class="lov-table-detail-row">
                                      <td colspan="7">
                                        <div style="display:flex; flex-direction:column; gap:10px;">
                                          <div style="font-size:13px; color:var(--pacom-text-body);">
                                            <strong style="font-weight:500; color:var(--pacom-text-primary);">诊断建议：</strong>${getRecommendation(a)}
                                          </div>
                                          <div style="display:flex; justify-content:space-between; align-items:center; gap:12px; flex-wrap:wrap;">
                                            <div class="pacom-row-sub">
                                              告警编号 <code>${a.id}</code> · 设备编号 <code>${a.deviceId}</code> · 关联工单 ${a.workOrderId ?? '无'}
                                            </div>
                                            <div style="display:flex; gap:8px; align-items:center;">
                                              ${!isSnoozed && a.status === 'active' ? `<button class="pacom-btn" data-snooze="${a.id}">忽略 24h</button>` : ''}
                                              <button class="pacom-btn" data-locate-home="1">定位到空间总览 →</button>
                                            </div>
                                          </div>
                                        </div>
                                      </td>
                                    </tr>`
                                    : ''
                                }`;
                            })
                            .join('')}
                        </tbody>
                      </table>
                    </div>`
                }
              </section>`
              : `
              <section class="lov-table-card">
                <div class="lov-table-toolbar">
                  <div class="lov-table-toolbar-group" style="flex:1; min-width:220px;">
                    <input class="pacom-input" style="max-width:280px;" data-alarm-search placeholder="搜索工单标题、设备或编号…" value="${searchQuery}" aria-label="搜索工单" />
                  </div>
                  <span class="pacom-row-sub">共 ${visibleWorkOrders.length} 条工单</span>
                </div>
                ${
                  visibleWorkOrders.length === 0
                    ? `<div class="lov-empty-state"><strong>暂无符合条件的运维工单</strong><span>可在「实时告警」中一键将告警转为运维工单。</span></div>`
                    : `
                    <div class="lov-table-wrap">
                      <table class="lov-table">
                        <thead>
                          <tr>
                            <th>工单事项</th>
                            <th>关联设备与空间</th>
                            <th>创建时间</th>
                            <th style="text-align:right;">状态流转</th>
                          </tr>
                        </thead>
                        <tbody>
                          ${visibleWorkOrders
                            .map((w) => {
                              const dev = resolveDeviceDisplay(w.deviceId);
                              return `
                                <tr>
                                  <td>
                                    <div style="font-weight:500;">${w.title}</div>
                                    <div class="pacom-row-sub">${w.description} · <code>${w.id}</code></div>
                                  </td>
                                  <td>
                                    <div style="font-weight:500;">${dev.name}</div>
                                    <div class="pacom-row-sub">${dev.zone}</div>
                                  </td>
                                  <td><span class="pacom-row-sub">${w.createdAt ? w.createdAt.slice(5, 16).replace('T', ' ') : '-'}</span></td>
                                  <td style="text-align:right;">
                                    <select class="pacom-select" data-wo-status="${w.id}" aria-label="更新工单状态">
                                      ${(['open', 'assigned', 'in_progress', 'resolved', 'closed'] as WorkOrderStatus[])
                                        .map((st) => `<option value="${st}" ${w.status === st ? 'selected' : ''}>${WO_STATUS_LABELS[st]}</option>`)
                                        .join('')}
                                    </select>
                                  </td>
                                </tr>`;
                            })
                            .join('')}
                        </tbody>
                      </table>
                    </div>`
                }
              </section>`
          }
        </div>
      </div>
    `;

    root.querySelectorAll<HTMLButtonElement>('[data-main-tab]').forEach((btn) => {
      btn.addEventListener('click', () => {
        activeTab = (btn.dataset.mainTab as 'alarms' | 'workorders') ?? 'alarms';
        notice = '';
        render();
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-kpi-filter]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const val = btn.dataset.kpiFilter;
        notice = '';
        if (val === 'workorders') {
          activeTab = 'workorders';
          openWoOnly = !openWoOnly;
        } else if (val === 'active' || val === 'acknowledged' || val === 'snoozed') {
          activeTab = 'alarms';
          statusFilter = statusFilter === val ? 'all' : val;
        }
        render();
      });
    });

    root.querySelector<HTMLButtonElement>('[data-clear-kpi]')?.addEventListener('click', () => {
      statusFilter = 'all';
      render();
    });

    root.querySelector<HTMLButtonElement>('[data-refresh-alarms]')?.addEventListener('click', () => {
      notice = '';
      void refresh();
    });

    root.querySelector<HTMLButtonElement>('[data-toggle-group]')?.addEventListener('click', () => {
      groupByRootCause = !groupByRootCause;
      render();
    });

    root.querySelector<HTMLButtonElement>('[data-toggle-open-wo]')?.addEventListener('click', () => {
      openWoOnly = !openWoOnly;
      render();
    });

    root.querySelector<HTMLSelectElement>('[data-severity-filter]')?.addEventListener('change', (e) => {
      severityFilter = (e.currentTarget as HTMLSelectElement).value;
      render();
    });

    const searchInput = root.querySelector<HTMLInputElement>('[data-alarm-search]');
    searchInput?.addEventListener('input', (e) => {
      const target = e.currentTarget as HTMLInputElement;
      const pos = target.selectionStart ?? target.value.length;
      searchQuery = target.value;
      render();
      const next = root.querySelector<HTMLInputElement>('[data-alarm-search]');
      if (next) {
        next.focus();
        next.setSelectionRange(pos, pos);
      }
    });

    root.querySelectorAll<HTMLInputElement>('[data-check-alarm]').forEach((chk) => {
      chk.addEventListener('change', () => {
        const id = chk.dataset.checkAlarm;
        if (!id) return;
        if (chk.checked) selectedAlarmIds.add(id);
        else selectedAlarmIds.delete(id);
        render();
      });
    });

    root.querySelector<HTMLButtonElement>('[data-batch-ack]')?.addEventListener('click', async () => {
      errorMsg = '';
      const ids = Array.from(selectedAlarmIds);
      try {
        for (const id of ids) {
          await adapter.acknowledgeAlarm(id, '告警中心批量确认');
          selfActionedIds.add(id);
        }
        selectedAlarmIds.clear();
        notice = `已批量确认 ${ids.length} 条告警，未来 24 小时持续校验无复发。`;
        await refresh();
      } catch (err) {
        errorMsg = err instanceof Error ? err.message : String(err);
        render();
      }
    });

    root.querySelectorAll<HTMLButtonElement>('[data-expand-alarm]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const id = btn.dataset.expandAlarm ?? null;
        expandedAlarmId = expandedAlarmId === id ? null : id;
        render();
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-locate-home]').forEach((btn) => {
      btn.addEventListener('click', () => {
        window.location.hash = '#home';
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-snooze]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const id = btn.dataset.snooze;
        if (!id) return;
        snoozedIds.add(id);
        selectedAlarmIds.delete(id);
        notice = '已将该告警限时忽略 24 小时，可在上方「已忽略 24h」磁贴中随时恢复。';
        render();
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-unsnooze]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const id = btn.dataset.unsnooze;
        if (!id) return;
        snoozedIds.delete(id);
        notice = '已恢复该告警的实时监控。';
        render();
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-mark-actioned]').forEach((btn) => {
      btn.addEventListener('click', async () => {
        errorMsg = '';
        const id = btn.dataset.markActioned!;
        try {
          await adapter.acknowledgeAlarm(id, '现场自处理完成（Mark Actioned）');
          selfActionedIds.add(id);
          selectedAlarmIds.delete(id);
          notice = '已标记处置完成，系统将在未来 24 小时持续校验是否复发。';
          await refresh();
        } catch (err) {
          errorMsg = err instanceof Error ? err.message : String(err);
          render();
        }
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-to-wo]').forEach((btn) => {
      btn.addEventListener('click', async () => {
        errorMsg = '';
        const alm = alarms.find((a) => a.id === btn.dataset.toWo);
        if (!alm) return;
        try {
          await adapter.createWorkOrder({
            floorId: alm.floorId,
            deviceId: alm.deviceId,
            alarmId: alm.id,
            title: `处置告警：${alm.title}`,
            description: alm.message,
          });
          notice = `已将「${alm.title}」转为运维工单。`;
          await refresh();
        } catch (err) {
          errorMsg = err instanceof Error ? err.message : String(err);
          render();
        }
      });
    });

    root.querySelectorAll<HTMLSelectElement>('[data-wo-status]').forEach((sel) => {
      sel.addEventListener('change', async () => {
        errorMsg = '';
        try {
          await adapter.updateWorkOrderStatus(sel.dataset.woStatus!, sel.value as WorkOrderStatus);
          notice = '工单状态已更新并写入审计日志。';
          await refresh();
        } catch (err) {
          errorMsg = err instanceof Error ? err.message : String(err);
          await refresh();
        }
      });
    });
  }

  await refresh();
}
