import type { ControlBatch, ProjectRuntimeSettings, SceneDefinition, UserSession } from '@pacom/contracts';
import { E7F_IDS, type PacomDataAdapter } from '../../adapters';

type StrategyTab = 'manual' | 'schedule_oss' | 'rules';
type OssMode = 'comfort' | 'balanced' | 'savings';
type RuleCategoryFilter = 'all' | 'lighting' | 'hvac' | 'alarm_rules';

const STRATEGY_RULE_CATEGORIES = new Set(['lighting', 'hvac', 'alarm_rules']);

const RULE_CATEGORY_LABELS: Record<string, string> = {
  lighting: '照明',
  hvac: '暖通',
  alarm_rules: '告警',
};

const OSS_MODES: Array<{
  id: OssMode;
  title: string;
  badge: string;
  desc: string;
  estSaving: string;
  predictedStart: string;
  savedHours: string;
}> = [
  {
    id: 'comfort',
    title: '舒适优先',
    badge: '100% 准点达温',
    desc: '所有功能区在入驻时刻前全部达到设定温度，适合重要接待与精密实验时段。',
    estSaving: '预计节能 4%–6%',
    predictedStart: '08:02（提前 28 分钟）',
    savedHours: '2.4 小时',
  },
  {
    id: 'balanced',
    title: '均衡节能（推荐）',
    badge: '动态预冷/预热',
    desc: '结合室外气象与历史热特性智能推迟开机，兼顾实验与办公舒适度。',
    estSaving: '预计节能 10%–14%',
    predictedStart: '08:12（推迟 18 分钟）',
    savedHours: '6.5 小时',
  },
  {
    id: 'savings',
    title: '极致节能',
    badge: '无人区零新风',
    desc: '优先保障核心有人员区域，非占用区自动切入值守温区并降低新风负荷。',
    estSaving: '预计节能 16%–22%',
    predictedStart: '08:21（推迟 27 分钟）',
    savedHours: '10.8 小时',
  },
];

interface ScheduleRow {
  id: string;
  name: string;
  windowLabel: string;
  scope: string;
  ossManaged: boolean;
  startHour: number;
  endHour: number;
  enabled: boolean;
}

function getSceneSubsystems(scene: SceneDefinition): string[] {
  const tags = new Set<string>();
  for (const a of scene.actions) {
    if (a.command.startsWith('lighting')) tags.add('照明');
    else if (a.command.startsWith('hvac')) tags.add('暖通');
    else tags.add('综合');
  }
  return Array.from(tags);
}

function renderTimelineBar(startHour: number, endHour: number, active: boolean): string {
  const color = active ? 'var(--pacom-accent-solid)' : 'var(--pacom-text-muted)';
  const spans =
    startHour < endHour
      ? `<div style="position:absolute; left:${(startHour / 24) * 100}%; width:${((endHour - startHour) / 24) * 100}%; top:0; bottom:0; border-radius:999px; background:${color};"></div>`
      : `
        <div style="position:absolute; left:${(startHour / 24) * 100}%; width:${((24 - startHour) / 24) * 100}%; top:0; bottom:0; border-radius:999px; background:${color};"></div>
        <div style="position:absolute; left:0; width:${(endHour / 24) * 100}%; top:0; bottom:0; border-radius:999px; background:${color};"></div>`;

  return `
    <div style="width:150px; display:flex; flex-direction:column; gap:3px;">
      <div style="position:relative; height:6px; border-radius:999px; background:var(--pacom-surface-recessed); overflow:hidden;">
        ${spans}
      </div>
      <div style="display:flex; justify-content:space-between; font-size:10px; color:var(--pacom-text-muted);">
        <span>00</span><span>12</span><span>24</span>
      </div>
    </div>
  `;
}

export async function mountScenesView(
  root: HTMLElement,
  adapter: PacomDataAdapter,
  session: UserSession
): Promise<void> {
  let [scenes, runtimeData]: [SceneDefinition[], ProjectRuntimeSettings] = await Promise.all([
    adapter.listScenes(E7F_IDS.floorId),
    adapter.getRuntimeSettings(E7F_IDS.projectId),
  ]);

  let activeTab: StrategyTab = 'manual';
  let ossMode: OssMode = 'balanced';
  let ruleCatFilter: RuleCategoryFilter = 'all';
  let activeBatch: ControlBatch | null = null;
  let searchQuery = '';
  let showCreateForm = false;
  let notice = '';
  let errorMsg = '';

  const schedules: ScheduleRow[] = [
    {
      id: 'sch-morning',
      name: '工作日早间预冷与公区启动',
      windowLabel: `周一至周五 · ${runtimeData.calendar.workdayStart} – ${runtimeData.calendar.workdayEnd}（节假日跳过）`,
      scope: 'E7F 全部空调与公区照明',
      ossManaged: true,
      startHour: 8.5,
      endHour: 18.5,
      enabled: true,
    },
    {
      id: 'sch-noon',
      name: '午间办公区柔光节能（50%）',
      windowLabel: '周一至周五 · 12:15 – 13:45',
      scope: 'E7F 开放办公区照明',
      ossManaged: false,
      startHour: 12.25,
      endHour: 13.75,
      enabled: true,
    },
    {
      id: 'sch-night',
      name: '夜间值守巡检与非必要回路关闭',
      windowLabel: `每日 · ${runtimeData.calendar.nightGuardStart} – 次日 ${runtimeData.calendar.nightGuardEnd}`,
      scope: 'E7F 非实验室区域',
      ossManaged: false,
      startHour: 21.5,
      endHour: 6.5,
      enabled: true,
    },
  ];

  const unsub = adapter.subscribeFloorEvents(E7F_IDS.floorId, async (event) => {
    if (event.type === 'control.receipt.updated' && activeBatch?.batchId === event.batchId) {
      activeBatch = await adapter.getControlBatch(event.batchId);
      render();
    }
  });

  function render(): void {
    const q = searchQuery.trim().toLowerCase();
    const visibleScenes = q
      ? scenes.filter((s) => `${s.name} ${s.description}`.toLowerCase().includes(q))
      : scenes;

    const allStrategyRules = runtimeData.rules.filter((r) => STRATEGY_RULE_CATEGORIES.has(r.category));
    const visibleRules =
      ruleCatFilter === 'all'
        ? allStrategyRules
        : allStrategyRules.filter((r) => r.category === ruleCatFilter);

    const activeOss = OSS_MODES.find((m) => m.id === ossMode) ?? OSS_MODES[1]!;
    const canControl = session.scope.canControlDevices;
    const canEditRules = session.scope.canEditDeployment;

    root.innerHTML = `
      <div class="pacom-shell">
        <header class="pacom-header">
          <div class="pacom-header-top">
            <div style="display:flex; align-items:center; gap:14px; flex-wrap:wrap;">
              <h1 class="pacom-title">智能策略</h1>
              <div class="pacom-tabs" role="tablist" aria-label="智能策略分类">
                <button class="pacom-tab" role="tab" aria-selected="${activeTab === 'manual'}" data-scene-tab="manual">快捷场景（${scenes.length}）</button>
                <button class="pacom-tab" role="tab" aria-selected="${activeTab === 'schedule_oss'}" data-scene-tab="schedule_oss">排程与节能</button>
                <button class="pacom-tab" role="tab" aria-selected="${activeTab === 'rules'}" data-scene-tab="rules">条件联动（${allStrategyRules.length}）</button>
              </div>
            </div>

            <div class="pacom-header-meta">
              <span class="pacom-badge ${canControl ? 'pacom-badge--online' : 'pacom-badge--warning'}">
                ${canControl ? '可执行并核验回执' : '只读权限'}
              </span>
              ${
                activeTab === 'manual'
                  ? `<button class="pacom-btn pacom-btn--primary" data-toggle-create="1">${showCreateForm ? '收起新建表单' : '+ 新建场景'}</button>`
                  : ''
              }
            </div>
          </div>

          <div class="pacom-header-toolbar">
            <span class="pacom-row-sub">安全执行优先级：人工覆盖 &gt; 快捷场景 &gt; 条件联动 &gt; 排程与节能（现场手动操作始终优先）</span>
          </div>
        </header>

        <div class="pacom-content-page" style="padding:4px 0 28px;">
          ${notice ? `<div class="lov-banner lov-banner--ok"><span class="lov-banner-title">${notice}</span></div>` : ''}
          ${errorMsg ? `<div class="pacom-alert-banner">${errorMsg}</div>` : ''}

          ${
            activeTab === 'manual'
              ? `
              ${
                activeBatch
                  ? `
                  <section class="lov-section">
                    <div class="lov-section-head">
                      <div style="display:flex; align-items:center; gap:8px;">
                        <h2 class="lov-section-title">最近执行逐设备回执</h2>
                        <span class="pacom-badge pacom-badge--accent">批次 ${activeBatch.batchId}</span>
                      </div>
                      <button class="pacom-btn pacom-btn--ghost" data-close-batch="1">关闭回执</button>
                    </div>
                    <div class="lov-table-card">
                      <div class="lov-table-wrap">
                        <table class="lov-table">
                          <thead>
                            <tr>
                              <th>目标设备</th>
                              <th>下发指令</th>
                              <th>目标值</th>
                              <th>回读状态</th>
                            </tr>
                          </thead>
                          <tbody>
                            ${activeBatch.receipts
                              .map(
                                (r) => `
                                <tr>
                                  <td><code style="font-size:12px;">${r.deviceId}</code></td>
                                  <td>${r.command}</td>
                                  <td>${String(r.targetValue)}${r.errorMessage ? `<div class="pacom-row-sub" style="color:var(--pacom-status-critical);">${r.errorMessage}</div>` : ''}</td>
                                  <td>
                                    <span class="pacom-badge ${r.status === 'verified_success' ? 'pacom-badge--online' : r.status === 'timeout' ? 'pacom-badge--critical' : 'pacom-badge--accent'}">${r.status}</span>
                                  </td>
                                </tr>`
                              )
                              .join('')}
                          </tbody>
                        </table>
                      </div>
                    </div>
                  </section>`
                  : ''
              }

              ${
                showCreateForm
                  ? `
                  <section class="lov-section">
                    <h2 class="lov-section-title">新建快捷场景</h2>
                    <form class="lov-settings-card" data-role="new-scene-form">
                      <div class="lov-setting-row">
                        <div class="lov-setting-meta">
                          <span class="lov-setting-title">场景名称</span>
                          <span class="lov-setting-desc">简明描述触发意图，例如「实验区午休调光」「来访接待模式」</span>
                        </div>
                        <div class="lov-setting-control" style="width:min(320px,100%);">
                          <input class="pacom-input" name="name" placeholder="输入场景名称" required />
                        </div>
                      </div>
                      <div class="lov-setting-row">
                        <div class="lov-setting-meta">
                          <span class="lov-setting-title">联动动作说明</span>
                          <span class="lov-setting-desc">保存后默认绑定 E7F 照明示例动作，点击执行即可实时核验逐设备回读</span>
                        </div>
                        <div class="lov-setting-control" style="width:min(320px,100%);">
                          <input class="pacom-input" name="description" placeholder="输入动作与预期效果" required />
                        </div>
                      </div>
                      <div class="lov-setting-row" style="justify-content:flex-end;">
                        <button class="pacom-btn" type="button" data-toggle-create="1">取消</button>
                        <button class="pacom-btn pacom-btn--primary" type="submit">保存场景</button>
                      </div>
                    </form>
                  </section>`
                  : ''
              }

              <div class="lov-table-toolbar" style="padding:0; border:0;">
                <input class="pacom-input" style="max-width:300px;" data-scene-search placeholder="搜索快捷场景名称或说明…" value="${searchQuery}" aria-label="搜索快捷场景" />
                <span class="pacom-row-sub">共 ${visibleScenes.length} 个一键场景</span>
              </div>

              <div style="display:grid; grid-template-columns:repeat(auto-fill,minmax(320px,1fr)); gap:14px;">
                ${
                  visibleScenes.length === 0
                    ? `<div class="pacom-card" style="grid-column:1/-1;"><div class="lov-empty-state"><strong>暂无匹配场景</strong><span>可清空搜索条件或点击右上角新建快捷场景。</span></div></div>`
                    : visibleScenes
                        .map((s) => {
                          const tags = getSceneSubsystems(s);
                          return `
                            <section class="pacom-card" style="gap:10px;">
                              <div style="display:flex; justify-content:space-between; align-items:center; gap:8px;">
                                <strong style="font-size:15px; font-weight:500;">${s.name}</strong>
                                <div style="display:flex; gap:4px; flex-wrap:wrap;">
                                  ${tags.map((t) => `<span class="pacom-badge pacom-badge--accent">${t}</span>`).join('')}
                                  <span class="pacom-badge pacom-badge--neutral">${s.actions.length} 动作</span>
                                </div>
                              </div>
                              <p style="margin:0; font-size:13px; color:var(--pacom-text-secondary); line-height:20px;">${s.description}</p>
                              <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; padding-top:8px; border-top:var(--hw) solid var(--pacom-border-subtle); margin-top:auto;">
                                <div class="pacom-row-sub">
                                  最近执行：${s.lastExecutedAt ? s.lastExecutedAt.slice(5, 16).replace('T', ' ') : '尚未执行'}
                                </div>
                                <button class="pacom-btn pacom-btn--primary" data-exec-scene="${s.id}" ${!canControl ? 'disabled' : ''}>一键执行</button>
                              </div>
                            </section>`;
                        })
                        .join('')
                }
              </div>`
              : activeTab === 'schedule_oss'
                ? `
                <div class="lov-kpi-strip" role="region" aria-label="优化启停运行状态">
                  <div class="lov-kpi-cell">
                    <span class="lov-kpi-label">当前优化启停模式</span>
                    <div class="lov-kpi-value" style="font-size:18px;">${activeOss.title}</div>
                    <span class="lov-kpi-delta">${activeOss.estSaving}</span>
                  </div>
                  <div class="lov-kpi-cell">
                    <span class="lov-kpi-label">明日预测预启动时刻</span>
                    <div class="lov-kpi-value" style="font-size:18px;">${activeOss.predictedStart}</div>
                    <span class="lov-kpi-delta">结合室外气象与热惯性动态计算</span>
                  </div>
                  <div class="lov-kpi-cell">
                    <span class="lov-kpi-label">本周累计节省运行工时</span>
                    <div class="lov-kpi-value" style="font-size:18px;">${activeOss.savedHours}</div>
                    <span class="lov-kpi-delta">异常通信时自动回退本地默认工况</span>
                  </div>
                </div>

                <section class="lov-section">
                  <div class="lov-section-head">
                    <h2 class="lov-section-title">智能启停节能策略（OSS）</h2>
                    <span class="pacom-row-sub">作用于下方标记为「OSS 托管」的排程</span>
                  </div>
                  <div class="lov-mode-grid">
                    ${OSS_MODES.map(
                      (m) => `
                      <button type="button" class="lov-mode-card" aria-pressed="${ossMode === m.id}" data-oss-mode="${m.id}" ${!canControl ? 'disabled' : ''}>
                        <div style="display:flex; justify-content:space-between; align-items:center; gap:8px;">
                          <strong style="font-size:15px; font-weight:500;">${m.title}</strong>
                          <span class="pacom-badge ${ossMode === m.id ? 'pacom-badge--online' : 'pacom-badge--neutral'}">${ossMode === m.id ? '当前生效' : m.badge}</span>
                        </div>
                        <span class="lov-setting-desc">${m.desc}</span>
                        <span class="pacom-row-sub" style="margin-top:4px; color:var(--pacom-text-primary); font-weight:500;">${m.estSaving}</span>
                      </button>`
                    ).join('')}
                  </div>
                </section>

                <section class="lov-section">
                  <div class="lov-section-head">
                    <h2 class="lov-section-title">E7F 自动排程时间表</h2>
                    <button class="pacom-btn" data-go-settings="1">调整项目工作日历 →</button>
                  </div>
                  <div class="lov-table-card">
                    <div class="lov-table-wrap">
                      <table class="lov-table">
                        <thead>
                          <tr>
                            <th>排程任务</th>
                            <th>24 小时覆盖时段</th>
                            <th>联动范围</th>
                            <th style="text-align:right;">启停状态</th>
                          </tr>
                        </thead>
                        <tbody>
                          ${schedules
                            .map(
                              (sc) => `
                              <tr>
                                <td>
                                  <div style="font-weight:500; display:flex; align-items:center; gap:6px; flex-wrap:wrap;">
                                    <span>${sc.name}</span>
                                    ${sc.ossManaged ? `<span class="pacom-badge pacom-badge--accent">OSS 托管</span>` : ''}
                                  </div>
                                  <div class="pacom-row-sub">${sc.windowLabel}</div>
                                </td>
                                <td>${renderTimelineBar(sc.startHour, sc.endHour, sc.enabled)}</td>
                                <td><span class="pacom-row-sub">${sc.scope}</span></td>
                                <td>
                                  <div style="display:flex; justify-content:flex-end; align-items:center; gap:8px;">
                                    <span class="pacom-row-sub">${sc.enabled ? '已启用' : '已暂停'}</span>
                                    <button
                                      type="button"
                                      class="lov-switch"
                                      role="switch"
                                      aria-checked="${sc.enabled}"
                                      aria-label="切换排程 ${sc.name}"
                                      data-toggle-schedule="${sc.id}"
                                      ${!canControl ? 'disabled' : ''}
                                    >
                                      <span class="lov-switch-thumb"></span>
                                    </button>
                                  </div>
                                </td>
                              </tr>`
                            )
                            .join('')}
                        </tbody>
                      </table>
                    </div>
                  </div>
                </section>`
                : `
                <section class="lov-section">
                  <div class="lov-section-head">
                    <h2 class="lov-section-title">事件与传感器条件联动规则（IF → THEN）</h2>
                    <div class="lov-count-pills" role="group" aria-label="按系统筛选规则">
                      ${(['all', 'lighting', 'hvac', 'alarm_rules'] as RuleCategoryFilter[])
                        .map((cat) => {
                          const label = cat === 'all' ? '全部' : (RULE_CATEGORY_LABELS[cat] ?? cat);
                          const count = cat === 'all' ? allStrategyRules.length : allStrategyRules.filter((r) => r.category === cat).length;
                          return `
                            <button type="button" class="lov-count-pill" aria-pressed="${ruleCatFilter === cat}" data-rule-cat="${cat}">
                              <span>${label}</span><span class="lov-count-num">${count}</span>
                            </button>`;
                        })
                        .join('')}
                    </div>
                  </div>
                  <div class="lov-settings-card">
                    ${
                      visibleRules.length === 0
                        ? `<div class="lov-empty-state"><strong>该分类下暂无条件联动规则</strong><span>可切换上方分类胶囊查看全部规则。</span></div>`
                        : visibleRules
                            .map(
                              (r) => `
                              <div class="lov-setting-row">
                                <div class="lov-setting-meta">
                                  <span class="lov-setting-title">
                                    <span class="pacom-badge pacom-badge--accent">${RULE_CATEGORY_LABELS[r.category] ?? r.category}</span>
                                    <span>${r.name}</span>
                                    <span class="pacom-badge pacom-badge--neutral">v${r.version}</span>
                                  </span>
                                  <span class="lov-setting-desc">${r.summary} · 范围：${r.scopeLabel} · 回执：${r.receiptSummary ?? '已同步'}</span>
                                </div>
                                <div class="lov-setting-control">
                                  <span class="pacom-row-sub">${r.enabled ? '已启用' : '已停用'}</span>
                                  <button
                                    type="button"
                                    class="lov-switch"
                                    role="switch"
                                    aria-checked="${r.enabled ? 'true' : 'false'}"
                                    aria-label="切换 ${r.name}"
                                    data-toggle-strategy-rule="${r.id}"
                                    data-rule-ver="${r.version}"
                                    data-rule-next="${!r.enabled}"
                                    ${!canEditRules ? 'disabled' : ''}
                                  >
                                    <span class="lov-switch-thumb"></span>
                                  </button>
                                </div>
                              </div>`
                            )
                            .join('')
                    }
                  </div>
                </section>`
          }
        </div>
      </div>
    `;

    root.querySelectorAll<HTMLButtonElement>('[data-scene-tab]').forEach((btn) => {
      btn.addEventListener('click', () => {
        activeTab = (btn.dataset.sceneTab as StrategyTab) ?? 'manual';
        notice = '';
        render();
      });
    });

    root.querySelector<HTMLButtonElement>('[data-close-batch]')?.addEventListener('click', () => {
      activeBatch = null;
      render();
    });

    root.querySelector<HTMLButtonElement>('[data-go-settings]')?.addEventListener('click', () => {
      window.location.hash = '#settings';
    });

    root.querySelectorAll<HTMLButtonElement>('[data-oss-mode]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const next = btn.dataset.ossMode as OssMode | undefined;
        if (!next) return;
        ossMode = next;
        const meta = OSS_MODES.find((m) => m.id === next);
        notice = `已切换至「${meta?.title ?? next}」模式（明日预测启动 ${meta?.predictedStart ?? ''}）。`;
        render();
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-toggle-schedule]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const id = btn.dataset.toggleSchedule;
        const item = schedules.find((s) => s.id === id);
        if (!item) return;
        item.enabled = !item.enabled;
        notice = `排程「${item.name}」已${item.enabled ? '恢复启用' : '临时暂停'}。`;
        render();
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-rule-cat]').forEach((btn) => {
      btn.addEventListener('click', () => {
        ruleCatFilter = (btn.dataset.ruleCat as RuleCategoryFilter) ?? 'all';
        render();
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-toggle-strategy-rule]').forEach((btn) => {
      btn.addEventListener('click', async () => {
        errorMsg = '';
        try {
          await adapter.toggleRuntimeRule(
            btn.dataset.toggleStrategyRule!,
            btn.dataset.ruleNext === 'true',
            Number(btn.dataset.ruleVer)
          );
          runtimeData = await adapter.getRuntimeSettings(E7F_IDS.projectId);
          notice = '条件联动规则状态与版本回执已更新。';
          render();
        } catch (err) {
          errorMsg = err instanceof Error ? err.message : String(err);
          render();
        }
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-toggle-create]').forEach((btn) => {
      btn.addEventListener('click', () => {
        showCreateForm = !showCreateForm;
        render();
      });
    });

    const searchEl = root.querySelector<HTMLInputElement>('[data-scene-search]');
    searchEl?.addEventListener('input', (e) => {
      const target = e.currentTarget as HTMLInputElement;
      const pos = target.selectionStart ?? target.value.length;
      searchQuery = target.value;
      render();
      const next = root.querySelector<HTMLInputElement>('[data-scene-search]');
      if (next) {
        next.focus();
        next.setSelectionRange(pos, pos);
      }
    });

    root.querySelectorAll<HTMLButtonElement>('[data-exec-scene]').forEach((btn) => {
      btn.addEventListener('click', async () => {
        errorMsg = '';
        try {
          activeBatch = await adapter.executeScene(btn.dataset.execScene!);
          scenes = await adapter.listScenes(E7F_IDS.floorId);
          render();
        } catch (err) {
          errorMsg = err instanceof Error ? err.message : String(err);
          render();
        }
      });
    });

    root.querySelector<HTMLFormElement>('[data-role="new-scene-form"]')?.addEventListener('submit', async (e) => {
      e.preventDefault();
      const fd = new FormData(e.currentTarget as HTMLFormElement);
      try {
        await adapter.createScene({
          projectId: E7F_IDS.projectId,
          floorId: E7F_IDS.floorId,
          name: String(fd.get('name') ?? ''),
          description: String(fd.get('description') ?? ''),
          actions: [{ deviceId: 'dev-e7f-lt-01', command: 'lighting.dimming', targetValue: 50 }],
        });
        scenes = await adapter.listScenes(E7F_IDS.floorId);
        showCreateForm = false;
        notice = '快捷场景已保存。';
        render();
      } catch (err) {
        errorMsg = err instanceof Error ? err.message : String(err);
        render();
      }
    });
  }

  render();
  window.addEventListener('hashchange', () => unsub(), { once: true });
}
