function renderSvgChart(report: AnalysisReport): string {
  const maxVal = Math.max(...report.series.map((s) => Math.max(s.value, s.baseline ?? 0)), 1);
  const barW = 46;
  const gap = 34;
  const padL = 36;
  const chartW = Math.max(report.series.length * (barW + gap) + padL * 2, 620);
  const chartH = 220;
  const baseY = 178;
  const plotH = 138;

  const gridLines = [0, 0.25, 0.5, 0.75, 1]
    .map((ratio) => {
      const y = Math.round(baseY - ratio * plotH);
      return `<line x1="${padL - 8}" y1="${y}" x2="${chartW - 18}" y2="${y}" stroke="oklch(85.12% 0 107 / 0.55)" stroke-dasharray="${ratio === 0 ? '0' : '3 3'}" />`;
    })
    .join('');

  const bars = report.series
    .map((pt, i) => {
      const x = padL + i * (barW + gap);
      const h = Math.max(8, Math.round((pt.value / maxVal) * plotH));
      const y = baseY - h;
      const isOverBaseline = typeof pt.baseline === 'number' && pt.value > pt.baseline * 1.08;
      const faultShade = isOverBaseline
        ? `<rect x="${x - 8}" y="28" width="${barW + 16}" height="${baseY - 28}" rx="8" fill="oklch(58.53% 0.2203 26.56 / 0.09)" />`
        : '';
      const baseLineMark =
        typeof pt.baseline === 'number'
          ? `<line x1="${x - 5}" y1="${Math.round(baseY - (pt.baseline / maxVal) * plotH)}" x2="${x + barW + 5}" y2="${Math.round(baseY - (pt.baseline / maxVal) * plotH)}" stroke="var(--pacom-brand)" stroke-width="1.5" stroke-dasharray="3 2" opacity="0.6" />`
          : '';
      return `
        ${faultShade}
        ${baseLineMark}
        <rect x="${x}" y="${y}" width="${barW}" height="${h}" rx="7" fill="${isOverBaseline ? 'var(--pacom-status-warning)' : 'var(--pacom-accent-solid)'}" opacity="0.88" />
        <text x="${x + barW / 2}" y="${y - 8}" text-anchor="middle" font-size="11" font-weight="500" fill="var(--pacom-text-primary)">${pt.value}</text>
        <text x="${x + barW / 2}" y="${baseY + 22}" text-anchor="middle" font-size="11" fill="var(--pacom-text-secondary)">${pt.label}</text>
      `;
    })
    .join('');

  return `
    <svg viewBox="0 0 ${chartW} ${chartH}" style="width:100%; height:228px; display:block;" role="img" aria-label="${report.category} 趋势图">
      ${gridLines}
      ${bars}
    </svg>
  `;
}

function downloadReportCsv(report: AnalysisReport): void {
  const lines = [
    ['时段', `数值 (${report.unit})`, `基线 (${report.unit})`].join(','),
    ...report.series.map((s) => [s.label, String(s.value), s.baseline !== undefined ? String(s.baseline) : ''].join(',')),
  ];
  const blob = new Blob([`\uFEFF${lines.join('\n')}`], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `pacom-${report.category}-${report.range}.csv`;
  a.click();
  URL.revokeObjectURL(url);
}

export async function mountAnalysisView(
  root: HTMLElement,
  adapter: PacomDataAdapter,
  _session: UserSession
): Promise<void> {
  let category: AnalysisCategory = 'energy';
  let range: AnalysisRange = '7d';
  let scopeId: string = E7F_IDS.floorId;
  let chartMode: 'chart' | 'table' = 'chart';
  let showCanvas = false;
  let report: AnalysisReport | null = null;

  async function load(): Promise<void> {
    report = await adapter.getAnalysisReport(category, range, E7F_IDS.floorId);
    render();
  }

  function render(): void {
    if (!report) return;
    const activeCat = CATEGORY_META.find((c) => c.id === category) ?? CATEGORY_META[0];
    const activeScope = SCOPE_OPTIONS.find((s) => s.id === scopeId) ?? SCOPE_OPTIONS[0]!;
    const warningZones = report.zoneBreakdown.filter((z) => z.status === 'warning');
    const breakdown = BREAKDOWN_BY_CATEGORY[category];
    const maxZoneVal = Math.max(...report.zoneBreakdown.map((z) => z.value), 1);

    root.innerHTML = `
      <div class="pacom-shell">
        <header class="pacom-header">
          <div class="pacom-header-top">
            <div style="display:flex; align-items:center; gap:12px; flex-wrap:wrap;">
              <h1 class="pacom-title">数据分析</h1>
              <div class="pacom-scope-pill" style="width:260px;" title="切换统计空间范围">
                <select data-scope-select aria-label="选择统计空间范围">
                  ${SCOPE_OPTIONS.map((s) => `<option value="${s.id}" ${s.id === scopeId ? 'selected' : ''}>${s.label}</option>`).join('')}
                </select>
                <span class="pacom-scope-chevron">▾</span>
              </div>
            </div>
            <div class="pacom-header-meta">
              <div class="pacom-tabs" role="group" aria-label="时间范围">
                <button class="pacom-tab" aria-selected="${range === 'today'}" data-range="today">今日</button>
                <button class="pacom-tab" aria-selected="${range === '7d'}" data-range="7d">近 7 天</button>
                <button class="pacom-tab" aria-selected="${range === '30d'}" data-range="30d">近 30 天</button>
              </div>
              <button class="pacom-btn" data-export-csv="1">导出 CSV</button>
              <button class="pacom-btn ${showCanvas ? 'pacom-btn--primary' : ''}" data-toggle-canvas="1">${showCanvas ? '关闭空间对照' : '空间对照'}</button>
            </div>
          </div>

          <div class="pacom-header-toolbar">
            <div class="pacom-tabs" role="tablist" aria-label="分析维度">
              ${CATEGORY_META.map(
                (c) => `<button class="pacom-tab" role="tab" aria-selected="${category === c.id}" data-cat="${c.id}">${c.label}</button>`
              ).join('')}
            </div>
            <span class="pacom-row-sub">口径：${activeScope.label} · 更新于 ${report.updatedAt.slice(5, 16).replace('T', ' ')}</span>
          </div>
        </header>

        <div class="pacom-content-page" style="padding:4px 0 28px;">
          <div class="lov-kpi-strip" role="region" aria-label="核心统计指标">
            ${report.kpis
              .map(
                (k) => `
                <div class="lov-kpi-cell">
                  <span class="lov-kpi-label">${k.label}</span>
                  <div class="lov-kpi-value">
                    <span>${k.value}</span>
                    ${k.unit ? `<span class="lov-kpi-unit">${k.unit}</span>` : ''}
                  </div>
                  <span class="lov-kpi-delta">${k.delta ?? '与基线持平'}</span>
                </div>`
              )
              .join('')}
          </div>

          <section class="lov-section">
            <div class="lov-section-head">
              <div style="display:flex; align-items:center; gap:10px; flex-wrap:wrap;">
                <h2 class="lov-section-title">${activeCat?.label ?? '趋势'}趋势（${report.unit}）</h2>
                <span class="pacom-badge pacom-badge--online">数据完整度 99.4%</span>
              </div>
              <div style="display:flex; align-items:center; gap:10px; flex-wrap:wrap;">
                <span class="pacom-row-sub">虚线为目标基线 · 浅红阴影为超基线异常段</span>
                <div class="pacom-tabs">
                  <button class="pacom-tab" aria-selected="${chartMode === 'chart'}" data-chart-mode="chart">趋势图</button>
                  <button class="pacom-tab" aria-selected="${chartMode === 'table'}" data-chart-mode="table">明细原表</button>
                </div>
              </div>
            </div>

            <div class="pacom-card" style="gap:16px;">
              ${
                chartMode === 'chart'
                  ? renderSvgChart(report)
                  : `
                  <div class="lov-table-wrap">
                    <table class="lov-table">
                      <thead>
                        <tr>
                          <th>统计时段</th>
                          <th>实测值（${report.unit}）</th>
                          <th>基线参考</th>
                          <th>状态</th>
                        </tr>
                      </thead>
                      <tbody>
                        ${report.series
                          .map((s) => {
                            const over = typeof s.baseline === 'number' && s.value > s.baseline * 1.08;
                            return `
                              <tr>
                                <td><strong>${s.label}</strong></td>
                                <td>${s.value}</td>
                                <td>${s.baseline ?? '-'}</td>
                                <td><span class="pacom-badge ${over ? 'pacom-badge--warning' : 'pacom-badge--online'}">${over ? '超基线' : '正常'}</span></td>
                              </tr>`;
                          })
                          .join('')}
                      </tbody>
                    </table>
                  </div>`
              }
              <div class="lov-banner">
                <div class="lov-banner-text">
                  <span class="lov-banner-title">${activeCat?.desc ?? '空间运行洞察'}</span>
                  <span class="lov-banner-sub">
                    ${
                      warningZones.length > 0
                        ? `当前有 ${warningZones.length} 个功能区指标偏高（${warningZones.map((z) => z.zoneName).join('、')}），建议前往智能策略优化启停时段。`
                        : breakdown.summary
                    }
                  </span>
                </div>
                <button class="pacom-btn" data-go-strategy="1">去智能策略优化 →</button>
              </div>
            </div>
          </section>

          <div class="lov-grid-2">
            <section class="lov-section">
              <div class="lov-section-head">
                <h2 class="lov-section-title">功能区排行对比</h2>
                <span class="pacom-row-sub">${report.zoneBreakdown.length} 个功能区</span>
              </div>
              <div class="lov-table-card">
                <div class="lov-table-wrap">
                  <table class="lov-table">
                    <thead>
                      <tr>
                        <th>功能区</th>
                        <th>占比分布</th>
                        <th>当前值</th>
                        <th>状态</th>
                      </tr>
                    </thead>
                    <tbody>
                      ${report.zoneBreakdown
                        .map((z) => {
                          const barPct = Math.max(8, Math.round((z.value / maxZoneVal) * 100));
                          return `
                            <tr>
                              <td style="font-weight:500;">${z.zoneName.replace(/^7F\s*/, '')}</td>
                              <td style="width:140px;">
                                <div style="height:6px; border-radius:999px; background:var(--pacom-surface-recessed); overflow:hidden;">
                                  <div style="width:${barPct}%; height:100%; border-radius:999px; background:${z.status === 'warning' ? 'var(--pacom-status-warning)' : 'var(--pacom-accent-solid)'};"></div>
                                </div>
                              </td>
                              <td><strong>${z.value}</strong> <span class="pacom-row-sub">${z.unit}</span></td>
                              <td>
                                <span class="pacom-badge ${z.status === 'warning' ? 'pacom-badge--warning' : 'pacom-badge--online'}">
                                  ${z.status === 'warning' ? '偏高关注' : '正常'}
                                </span>
                              </td>
                            </tr>`;
                        })
                        .join('')}
                    </tbody>
                  </table>
                </div>
              </div>
            </section>

            <section class="lov-section">
              <div class="lov-section-head">
                <h2 class="lov-section-title">${showCanvas ? 'E7F 空间对照预览' : breakdown.title}</h2>
                <span class="pacom-row-sub">${showCanvas ? '与空间总览状态独立' : '当前周期结构占比'}</span>
              </div>
              <div class="pacom-card" style="flex:1; justify-content:center; gap:14px;">
                ${
                  showCanvas
                    ? `<img class="pacom-plan-img" src="./media/7F.webp" alt="E7F 分析楼层预览" style="max-height:240px; margin:0 auto;" />`
                    : breakdown.items
                        .map(
                          (item) => `
                          <div style="display:flex; flex-direction:column; gap:6px;">
                            <div style="display:flex; justify-content:space-between; align-items:center; font-size:13px;">
                              <span style="font-weight:500; color:var(--pacom-text-primary);">${item.name}</span>
                              <span class="pacom-row-sub">${item.detail} · <strong style="color:var(--pacom-text-primary);">${item.pct}%</strong></span>
                            </div>
                            <div style="height:7px; border-radius:999px; background:var(--pacom-surface-recessed); overflow:hidden;">
                              <div style="width:${Math.min(100, item.pct)}%; height:100%; border-radius:999px; background:${item.color};"></div>
                            </div>
                          </div>`
                        )
                        .join('')
                }
              </div>
            </section>
          </div>
        </div>
      </div>
    `;

    root.querySelectorAll<HTMLButtonElement>('[data-cat]').forEach((btn) => {
      btn.addEventListener('click', () => {
        category = btn.dataset.cat as AnalysisCategory;
        void load();
      });
    });

    root.querySelector<HTMLSelectElement>('[data-scope-select]')?.addEventListener('change', (e) => {
      scopeId = (e.currentTarget as HTMLSelectElement).value;
      render();
    });

    root.querySelectorAll<HTMLButtonElement>('[data-range]').forEach((btn) => {
      btn.addEventListener('click', () => {
        range = (btn.dataset.range as AnalysisRange) ?? '7d';
        void load();
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-chart-mode]').forEach((btn) => {
      btn.addEventListener('click', () => {
        chartMode = (btn.dataset.chartMode as 'chart' | 'table') ?? 'chart';
        render();
      });
    });

    root.querySelector<HTMLButtonElement>('[data-export-csv]')?.addEventListener('click', () => {
      if (report) downloadReportCsv(report);
    });

    root.querySelector<HTMLButtonElement>('[data-toggle-canvas]')?.addEventListener('click', () => {
      showCanvas = !showCanvas;
      render();
    });

    root.querySelector<HTMLButtonElement>('[data-go-strategy]')?.addEventListener('click', () => {
      window.location.hash = '#scenes';
    });
  }

  await load();
}
